static inline bool
qar_peer_id_equals(const QarPeerId* id1, const QarPeerId* id2)
{
	if(id1 == NULL || id2 == NULL)
	{
		return false;
	}

	for(size_t i = 0; i < QAR_MAX_ID_LENGTH; i++)
	{
		if(id1->data[i] != id2->data[i])
		{
			return false;
		}
	}

	return true;
}

